actions.action:
zl_proces: f.zl_proces, zl_pridelene: f.zl_pridelene, zl_authority: f.zl_authority;

change zl_proces options { processOptions() }
change zl_authority options { authorityOptions() }
change zl_authority value { ["ROLE_USER"] }
change zl_pridelene value { "(zatiaľ nič)" }
changeCaseProperty("title").about { "Nový používateľ" }
changeCaseProperty("color").about { "blue" }

document.function:
{ def hodnota ->
    def mail = ((hodnota ?: "") as String).trim()
    return mail ==~ /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/
}

{ def pole ->
    def raw = pole.value
    if (raw == null) return []
    if (raw instanceof Collection) return raw.collect { it as String }
    if (raw.hasProperty("value") && raw.value instanceof Collection) {
        return raw.value.collect { it as String }
    }
    def s = (raw as String).trim()
    return s ? [s] : []
}

{ def zl_zoznam ->
    def out = []
    ((zl_zoznam.value ?: "") as String).split("\n").each { String riadok ->
        def r = riadok.trim()
        if (!r) return
        def casti = r.split("\\|", -1)
        if (casti.length < 2) return
        out << [rola: casti[0], siet: casti[1], verzia: (casti.length > 2 ? casti[2] : "vsetky")]
    }
    return out
}

{ def polozky ->
    if (!polozky) return "(zatiaľ nič)"
    return polozky.collect { p ->
        def v = (p.verzia == null || p.verzia == "" || p.verzia == "vsetky")
                ? "všetky verzie" : ("verzia " + (p.verzia as String).replace("_", "."))
        return "• " + p.rola + " — " + p.siet + " (" + v + ")"
    }.join("\n")
}

{ ->
    // Množina `pu_userid`, ktoré už majú prípad — načítaná JEDNÝM prechodom.
    // `findCases { it.dataSet... }` nefunguje (petriflow_reference, gotcha 40),
    // takže sa filtruje v Groovy.
    //
    // Pôvodne to bola funkcia `pripad_uctu(id)` volaná pre každý účet, čo je
    // jeden úplný prechod prípadmi na účet. Spolu s vtedy kvadratickým
    // `userSnapshot` na tom zosúladenie vytimeoutovalo.
    def out = [] as Set
    findCases({ it.processIdentifier.eq("pouzivatelia/pu_pouzivatel") }).each {
        def v = ((it.getFieldValue("pu_userid") ?: "") as String).trim()
        if (v) out << v
    }
    return out
}

{ def id ->
    // Prípad účtu.
    // Stačí zviazať. Meno, e-mail, oprávnenia aj role si prípad dotiahne z účtu
    // sám - má na to dátovú udalosť na `pu_userid`. Účet je zdroj pravdy.
    def c = createCase("pouzivatelia/pu_pouzivatel")
    setData("t_pu_uprava", c, ["pu_userid": ["value": id as String, "type": "text"]])
    return c
}

actions.action:
zl_proces: f.zl_proces, zl_roly: f.zl_roly, zl_verzia: f.zl_verzia;

def siet = (zl_proces.value ?: "") as String
change zl_roly options { processRoleOptions(siet) }
change zl_roly value { [] }
change zl_verzia options { processVersionOptions(siet) }
change zl_verzia value { "vsetky" }

zl_proces: f.zl_proces, zl_roly: f.zl_roly, zl_verzia: f.zl_verzia,
zl_zoznam: f.zl_zoznam, zl_pridelene: f.zl_pridelene;

def siet = (zl_proces.value ?: "") as String
def verzia = ((zl_verzia.value ?: "vsetky") as String)
def vybrane = ako_zoznam(zl_roly)
if (siet && vybrane) {
    def riadky = rozbor_zoznamu(zl_zoznam).collect { it.rola + "|" + it.siet + "|" + it.verzia }
    vybrane.each { String rola ->
        def r = rola + "|" + siet + "|" + verzia
        if (!riadky.contains(r)) { riadky << r }
    }
    change zl_zoznam value { riadky.join("\n") }
    change zl_roly value { [] }
}
change zl_pridelene value { popis_zoznamu(rozbor_zoznamu(zl_zoznam)) }

zl_zoznam: f.zl_zoznam, zl_pridelene: f.zl_pridelene;

change zl_zoznam value { "" }
change zl_pridelene value { "(zatiaľ nič)" }

zl_vysledok: f.zl_vysledok;

// Ucty vznikaju aj mimo tejto appky. Tlacidlo im doplni pripad; je idempotentne.
def pridane = []
def uz = 0
def maju = zviazane_ucty()
userOptions().each { String id, String popis ->
    if (maju.contains(id)) { uz++; return }
    def snap = userSnapshot(id)
    if (!snap || !snap.email) return
    zaloz_pripad(id)
    pridane << (snap.email as String)
}
change zl_vysledok value {
    "Zosúladenie účtov:\n" +
    "• prípad už mali: " + uz + "\n" +
    (pridane ? ("• prípad doplnený (" + pridane.size() + "): " + pridane.join(", "))
             : "• nič nebolo treba doplniť")
}

zl_proces: f.zl_proces;

// Pri kazdom otvoreni znova - inak by novo naimportovana appka v ponuke nebola.
change zl_proces options { processOptions() }
change zl_authority options { authorityOptions() }

zl_email: f.zl_email, zl_heslo: f.zl_heslo, zl_authority: f.zl_authority;

def mail = ((zl_email.value ?: "") as String).trim()
if (!je_email(mail)) {
    throw new java.lang.IllegalStateException("E-mail nemá platný tvar: " + mail)
}
if (findUserByEmail(mail) != null) {
    throw new java.lang.IllegalStateException("Používateľ s e-mailom " + mail + " už existuje.")
}
if (!registrationService.isPasswordSufficient((zl_heslo.value ?: "") as String)) {
    throw new java.lang.IllegalStateException("Heslo nespĺňa požiadavky instancie.")
}
if (!ako_zoznam(zl_authority).contains("ROLE_USER")) {
    throw new java.lang.IllegalStateException(
            "Bez ROLE_USER sa používateľ prihlási a neuvidí žiadne zobrazenie.")
}

zl_meno: f.zl_meno, zl_priezvisko: f.zl_priezvisko, zl_email: f.zl_email,
zl_heslo: f.zl_heslo, zl_authority: f.zl_authority, zl_zoznam: f.zl_zoznam,
zl_pridelene: f.zl_pridelene, zl_vysledok: f.zl_vysledok, zl_proces: f.zl_proces,
zl_roly: f.zl_roly, zl_verzia: f.zl_verzia;

def mail = ((zl_email.value ?: "") as String).trim()
def meno = ((zl_meno.value ?: "") as String).trim()
def priezvisko = ((zl_priezvisko.value ?: "") as String).trim()
def authorities = ako_zoznam(zl_authority)

def novy = createNewUser(meno, priezvisko, mail, (zl_heslo.value ?: "") as String, authorities)
def id = novy.stringId as String
def riadky = ["účet vytvorený: " + mail,
              "systémové oprávnenia: " + (authorities ? authorities.join(", ") : "žiadne")]

def pridelene = []
def zlyhane = []
rozbor_zoznamu(zl_zoznam).each { p ->
    if (setProcessRole(id, p.rola as String, p.siet as String, p.verzia as String, true)) {
        pridelene << (p.rola + " (" + p.siet + ")")
    } else {
        zlyhane << (p.rola + " (" + p.siet + ")")
    }
}
riadky << (pridelene ? "procesné role: " + pridelene.join(", ") : "procesné role: žiadne")
if (zlyhane) {
    riadky << ("NEPODARILO SA prideliť: " + zlyhane.join(", "))
}

// Ucet je entita - dostane vlastny pripad. Jeden ucet, jeden pripad.
def c = zaloz_pripad(id)
riadky << ("prípad účtu: " + c.stringId)

// Pult sa vyprazdni a je pripraveny na dalsi ucet. Bez tohto by tu zostali
// vypisane data predchadzajuceho cloveka - a heslo medzi nimi.
change zl_meno value { "" }
change zl_priezvisko value { "" }
change zl_email value { "" }
change zl_heslo value { "" }
change zl_authority value { ["ROLE_USER"] }
change zl_proces value { "" }
change zl_roly value { [] }
change zl_verzia value { "" }
change zl_zoznam value { "" }
change zl_pridelene value { "(zatiaľ nič)" }
change zl_vysledok value { riadky.join("\n") }

changeCaseProperty("title").about { "Nový používateľ" }
